#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long computePower(long long base, long long exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

long long modularInverse(long long a, long long m) {
    return computePower(a, m - 2);
}

int main() {
